/* From Uiverse.io by VijinV - Tags: input, animated */
.__UIV_SCOPE__ .inputbox {
  position: relative;
  width: 196px;
}

.__UIV_SCOPE__ .inputbox input {
  position: relative;
  width: 100%;
  padding: 20px 10px 10px;
  background: transparent;
  outline: none;
  box-shadow: none;
  border: none;
  color: #23242a;
  font-size: 1em;
  letter-spacing: 0.05em;
  transition: 0.5s;
  z-index: 10;
}

.__UIV_SCOPE__ .inputbox span {
  position: absolute;
  left: 0;
  padding: 20px 10px 10px;
  font-size: 1em;
  color: #8f8f8f;
  letter-spacing: 00.05em;
  transition: 0.5s;
  pointer-events: none;
}

.__UIV_SCOPE__ .inputbox input:valid ~span,
.__UIV_SCOPE__ .inputbox input:focus ~span {
  color: #45f3ff;
  transform: translateX(-10px) translateY(-34px);
  font-size: 0,75em;
}

.__UIV_SCOPE__ .inputbox i {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 2px;
  background: #45f3ff;
  border-radius: 4px;
  transition: 0.5s;
  pointer-events: none;
  z-index: 9;
}

.__UIV_SCOPE__ .inputbox input:valid ~i,
.__UIV_SCOPE__ .inputbox input:focus ~i {
  height: 44px;
}
